type Tok = { t: "num"; v: number } | { t: "end" };
class P {
  toks: Tok[];
  constructor(toks: Tok[]) {
    this.toks = toks;
  }
  at(i: number): number {
    const t = this.toks[i];
    if (t.t === "num") return t.v;
    return -1;
  }
}
function viaParam(p: P): number {
  const t = p.toks[0];
  if (t.t === "num") return t.v;
  return 0;
}
function main(): void {
  const p = new P([{ t: "num", v: 4 }, { t: "end" }]);
  console.log(p.at(0), p.at(1), viaParam(p));
}
